import { snake, pascal } from "./normalize.mjs";
const q = JSON.stringify;
export function emitRust(ir) {
  const { nodes, roots, methods, behavior: b } = ir;
  const out = [
    "// Code generated by native/codegen/generate.mjs; DO NOT EDIT.",
    "#![allow(clippy::large_enum_variant)]",
    "use serde::{Serialize, Deserialize};",
    "use serde_json::Value;",
    "use crate::codec::Presence;"
  ];
  function typ(id, body = false) {
    const n = nodes[id],
      s = n.schema;
    if (n.ref !== undefined) return nodes[n.ref].name;
    if (!body && (s.properties || s.oneOf || s.anyOf)) return n.name;
    if (s.oneOf || s.anyOf) return "Value";
    if (s.type === "array") return `Vec<${typ(n.branches.items)}>`;
    if (s.type === "object") return "std::collections::BTreeMap<String, Value>";
    if (Array.isArray(s.type)) {
      const other = s.type.filter((x) => x !== "null");
      if (other.length === 1 && s.type.includes("null")) return `Option<${scalar(other[0])}>`;
      return "Value";
    }
    return scalar(
      s.type ?? (s.const !== undefined ? typeof s.const : s.enum?.length ? typeof s.enum[0] : "")
    );
  }
  function scalar(t) {
    return (
      {
        string: "String",
        integer: "i64",
        number: "serde_json::Number",
        boolean: "bool",
        object: "std::collections::BTreeMap<String, Value>"
      }[t] ?? "Value"
    );
  }
  // 只为整数、可空整数和整数数组生成绑定器；未知对象保持 Value。
  function integerShape(id) {
    const n = nodes[id],
      s = n.schema;
    if (n.ref !== undefined) return integerShape(n.ref);
    if (s.type === "integer") return true;
    if (Array.isArray(s.type))
      return s.type.includes("integer") && s.type.every((t) => ["null", "integer"].includes(t));
    return s.type === "array" && n.branches.items !== undefined && integerShape(n.branches.items);
  }
  for (const n of nodes) {
    const s = n.schema;
    if (s.properties) {
      out.push("#[derive(Debug, Clone, Serialize, Deserialize)]", `pub struct ${n.name} {`);
      for (const [k, id] of Object.entries(n.properties)) {
        const required = s.required?.includes(k);
        out.push(
          `#[serde(rename = ${q(k)}${required ? "" : ', default, skip_serializing_if = "Presence::is_missing"'}${integerShape(id) ? ', deserialize_with = "crate::codec::deserialize_integers"' : ""})]`,
          `pub r#${snake(k) === "self" ? "self_value" : snake(k)}: ${required ? typ(id) : `Presence<${typ(id)}>`},`
        );
      }
      if (s.additionalProperties !== false)
        out.push("#[serde(flatten)]", "pub extra: std::collections::BTreeMap<String, Value>,");
      out.push("}");
    } else if (s.oneOf || s.anyOf) {
      out.push(
        "#[derive(Debug, Clone, Serialize, Deserialize)]",
        "#[serde(untagged)]",
        `pub enum ${n.name} {`
      );
      for (const [i, id] of (n.branches.oneOf ?? n.branches.anyOf).entries())
        out.push(
          `Variant${i}(${integerShape(id) ? '#[serde(deserialize_with = "crate::codec::deserialize_integers")] ' : ""}${typ(id)}),`
        );
      out.push("}");
    } else out.push(`pub type ${n.name} = ${typ(n.id, true)};`);
  }
  const rules = [
    "// Code generated by native/codegen/generate.mjs; DO NOT EDIT.",
    "// Schema property dispatch uses a uniform match, including one-property objects.",
    "#![allow(clippy::single_match, clippy::match_single_binding)]",
    "use serde_json::Value;",
    "use crate::codec::*;"
  ];
  rules.push("pub fn validate(name: &str, v: &Value) -> Result<(), Error> { match name {");
  for (const [k, v] of Object.entries(roots)) rules.push(`${q(k)} => node_${v}(v),`);
  rules.push('_ => Err(Error::new("UNKNOWN_DEFINITION")),}}');
  rules.push(
    "pub fn normalize_integer_root(name: &str, v: &mut Value) -> Result<(),Error> { let _ = v; match name {"
  );
  for (const [name, id] of Object.entries(roots))
    if (integerShape(id)) rules.push(`${q(name)} => normalize_integers(v),`);
  rules.push("_ => Ok(()), }}");
  for (const n of nodes) {
    const s = n.schema;
    rules.push(`pub fn node_${n.id}(v: &Value) -> Result<(), Error> { let _ = v;`);
    if (n.ref !== undefined) {
      rules.push(`node_${n.ref}(v)`, "}");
      continue;
    }
    if (s.type)
      rules.push(`types(v, &[${(Array.isArray(s.type) ? s.type : [s.type]).map(q).join(",")}])?;`);
    if (s.const !== undefined || s.enum)
      rules.push(
        `values(v, &[${(s.enum ?? [s.const]).map((x) => q(JSON.stringify(x))).join(",")}])?;`
      );
    for (const k of [
      "minimum",
      "maximum",
      "minLength",
      "maxLength",
      "minItems",
      "maxItems",
      "minProperties",
      "maxProperties"
    ])
      if (s[k] !== undefined) rules.push(`constraint(v, ${q(k)}, ${s[k]}i64)?;`);
    if (s.pattern) rules.push(`pattern(v, ${q(s.pattern)})?;`);
    if (s.required) rules.push(`required(v, &[${s.required.map(q).join(",")}])?;`);
    if (s.additionalProperties === false && Object.keys(n.properties).length === 0) {
      rules.push(
        'if v.as_object().is_some_and(|m| !m.is_empty()){return Err(Error::new("VALIDATION_ERROR"));}'
      );
    } else if (
      s.properties ||
      n.branches.additionalProperties !== undefined ||
      n.branches.propertyNames !== undefined
    ) {
      rules.push("if let Some(m) = v.as_object() { for (key, value) in m { let _ = value;");
      if (n.branches.propertyNames !== undefined)
        rules.push(`node_${n.branches.propertyNames}(&Value::String(key.clone()))?;`);
      rules.push("match key.as_str() {");
      for (const [k, id] of Object.entries(n.properties))
        rules.push(`${q(k)} => node_${id}(value)?,`);
      rules.push(
        `_ => ${s.additionalProperties === false ? 'return Err(Error::new("VALIDATION_ERROR"))' : n.branches.additionalProperties !== undefined ? `node_${n.branches.additionalProperties}(value)?` : "{}"},`,
        "}}}"
      );
    }
    if (n.branches.items !== undefined)
      rules.push(`if let Some(a) = v.as_array() { for x in a { node_${n.branches.items}(x)?; } }`);
    if (s.uniqueItems) rules.push("unique(v)?;");
    if (n.branches.contains !== undefined)
      rules.push(
        `if let Some(a)=v.as_array(){ if !a.iter().any(|x|node_${n.branches.contains}(x).is_ok()){return Err(Error::new("VALIDATION_ERROR"));}}`
      );
    for (const id of n.branches.allOf ?? []) rules.push(`node_${id}(v)?;`);
    for (const kind of ["oneOf", "anyOf"])
      if (n.branches[kind])
        rules.push(
          `if [${n.branches[kind].map((id) => `node_${id}(v).is_ok()`).join(",")}].iter().filter(|x| **x).count() ${kind === "oneOf" ? "!= 1" : "== 0"} {return Err(Error::new("VALIDATION_ERROR"));}`
        );
    if (n.branches.not !== undefined)
      rules.push(
        `if node_${n.branches.not}(v).is_ok(){return Err(Error::new("VALIDATION_ERROR"));}`
      );
    if (n.branches.if !== undefined)
      rules.push(
        `if node_${n.branches.if}(v).is_ok(){${n.branches.then !== undefined ? `node_${n.branches.then}(v)?;` : ""}}else{${n.branches.else !== undefined ? `node_${n.branches.else}(v)?;` : ""}}`
      );
    for (const [k, v] of Object.entries(s))
      if (k.startsWith("x-")) rules.push(`refinement(v,${q(k)},${v === true ? 1 : v})?;`);
    rules.push("Ok(())", "}");
  }
  rules.push(
    "pub type Validator = fn(&Value)->Result<(),Error>;",
    "pub type MethodRule = (Validator,Validator,bool);",
    "pub fn method(name: &str) -> Result<MethodRule,Error>{match name{"
  );
  for (const m of methods)
    rules.push(`${q(m.method)}=>Ok((node_${m.paramsId},node_${m.resultId},${m.sideEffect})),`);
  rules.push('_=>Err(Error::new("METHOD_NOT_FOUND")),}}');
  for (const [k, v] of Object.entries(b.limits))
    rules.push(`pub const LIMIT_${snake(k).toUpperCase()}: usize = ${v};`);
  for (const [k, v] of Object.entries(b.timeoutsMs))
    rules.push(`pub const TIMEOUT_${snake(k).toUpperCase()}: u64 = ${v};`);
  for (const [k, v] of Object.entries(b))
    if (Array.isArray(v))
      rules.push(
        `pub const ${snake(k).toUpperCase()}: &[${typeof v[0] === "number" ? "u64" : "&str"}] = &[${v.map((x) => (typeof x === "string" ? q(x) : x)).join(",")}];`
      );
  const rpc = [
    "// Code generated by native/codegen/generate.mjs; DO NOT EDIT.",
    "use crate::{Client, Error};",
    "use super::models::*;",
    "impl Client {"
  ];
  for (const m of methods)
    if (!m.stream)
      rpc.push(
        `pub async fn rpc_${snake(m.name)}(&self, params: ${nodes[m.paramsId].name}) -> Result<${nodes[m.resultId].name},Error> { let v=self.rpc(${q(m.method)},serde_json::to_value(params)?,None).await?; Ok(crate::codec::from_value(v)?) }`
      );
  rpc.push("}");
  return {
    "native/rust/src/generated/models.rs": out.join("\n") + "\n",
    "native/rust/src/generated/rules.rs": rules.join("\n").replaceAll("}else{}", "}") + "\n",
    "native/rust/src/generated/rpc.rs": rpc.join("\n") + "\n"
  };
}
